function setBtn(groupId, val) {
  document.getElementById(groupId).querySelectorAll('.optBtn').forEach(b => {
    b.classList.toggle('selected', b.dataset.val === val);
  });
}

function getUsers() {
  return JSON.parse(localStorage.getItem('explox_users') || '[]');
}
function saveUsers(arr) {
  localStorage.setItem('explox_users', JSON.stringify(arr));
}
function getPw(name)     { return localStorage.getItem('explox_pw_' + name) || ''; }
function setPw(name, pw) { localStorage.setItem('explox_pw_' + name, pw); }

function hashPassword(pw) {
  let h = 5381;
  for(let i = 0; i < pw.length; i++) h = (Math.imul(h, 33) ^ pw.charCodeAt(i)) >>> 0;
  return 'h_' + h.toString(16).padStart(8,'0') + '_' + pw.split('').reduce((a,c)=>a+c.charCodeAt(0),0);
}

// ─── ONLINE SERVER MODE ──────────────────────────────────────────────────────
// "Online" points at a temporary server the player can run on their own PC (see
// explox/server/). Free tunnel services hand out a NEW random address every
// time the server starts (that's what "temporary" means), so we can't hardcode
// one — instead a link like ?server=https://xxxx.example.com auto-fills it (the
// host shares that link), and it's remembered from then on until it's changed.
// When there's no server, or it's off, we fall back to the always-available
// Offline mode, which is exactly the local-only behavior this file always had.
const EXPLOX_DEFAULT_SERVER_URL = 'https://explox-server.onrender.com';
let serverMode = localStorage.getItem('explox_mode') || 'offline';
let EXPLOX_ONLINE_URL = localStorage.getItem('explox_server_url') || EXPLOX_DEFAULT_SERVER_URL;
if (EXPLOX_ONLINE_URL.includes('trycloudflare.com')) {
  // Old family-PC tunnel address, now retired — fall back to the permanent server.
  EXPLOX_ONLINE_URL = EXPLOX_DEFAULT_SERVER_URL;
  localStorage.setItem('explox_server_url', EXPLOX_ONLINE_URL);
}
(function seedServerUrlFromLink() {
  const fromLink = new URLSearchParams(location.search).get('server');
  if (fromLink) {
    EXPLOX_ONLINE_URL = fromLink.trim().replace(/\/+$/, '');
    localStorage.setItem('explox_server_url', EXPLOX_ONLINE_URL);
  }
})();

async function fetchWithTimeout(url, opts, timeoutMs) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs || 4000);
  try {
    return await fetch(url, Object.assign({}, opts, { signal: ctrl.signal }));
  } finally {
    clearTimeout(t);
  }
}

function showServerMsg(text) {
  const el = document.getElementById('serverStatusMsg');
  if(el) el.textContent = text || '';
}

function updateServerModeButtons() {
  const onBtn  = document.getElementById('onlineModeBtn');
  const offBtn = document.getElementById('offlineModeBtn');
  const urlBox = document.getElementById('serverUrlInput');
  if(onBtn)  onBtn.classList.toggle('modeActive', serverMode === 'online');
  if(offBtn) offBtn.classList.toggle('modeActive', serverMode === 'offline');
  if(urlBox) {
    // Always hidden now — there's a real default server (EXPLOX_DEFAULT_SERVER_URL), so
    // players never need to see or paste an address. Value stays synced for setServerMode()'s
    // read of it, and a ?server= link (or the empty-value fallback below) can still override it.
    urlBox.style.display = 'none';
    if(document.activeElement !== urlBox) urlBox.value = EXPLOX_ONLINE_URL;
  }
}

async function setServerMode(mode) {
  if(mode === 'online') {
    const urlBox = document.getElementById('serverUrlInput');
    const typed  = urlBox ? urlBox.value.trim().replace(/\/+$/, '') : '';
    if(!typed) {
      urlBox.style.display = 'block'; // reveal the address box (serverMode hasn't flipped to 'online' yet, so updateServerModeButtons() alone wouldn't show it)
      showServerMsg('👉 Paste the server address a friend shared with you, then click ONLINE again.');
      return;
    }
    EXPLOX_ONLINE_URL = typed;
    localStorage.setItem('explox_server_url', EXPLOX_ONLINE_URL);
    // A real bug, not a rare edge case: the free-tier host (Render) puts the server to sleep
    // after a period of no traffic, and the FIRST request after that has to wait for it to wake
    // back up — which can take 30-50+ seconds. The old 4-second timeout treated that completely
    // normal wake-up delay as "the server is off," so ANY player visiting after a quiet stretch
    // got a false "server is off" message and had no way to actually get Online. A real sleeping
    // server and a real broken one look identical to a short timeout — the fix is giving it
    // enough time to actually answer, with an honest "waking up" message so a 30+ second wait
    // doesn't look frozen.
    showServerMsg('🔄 Checking server (can take up to a minute if it was asleep)...');
    let up = false;
    try { up = (await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/health', {}, 45000)).ok; } catch(e) {}
    if(!up) {
      showServerMsg('😴 Sorry, the server is currently off. Please come again later or play Offline!');
      return;
    }
  }
  serverMode = mode;
  localStorage.setItem('explox_mode', mode);
  showServerMsg('');
  updateServerModeButtons();
  loadLoginScreen();
}

async function loadLoginScreen() {
  updateServerModeButtons();
  const list = document.getElementById('accountList');
  document.getElementById('newAccName').value = '';
  document.getElementById('newAccPw').value   = '';

  let names, sipFor, picFor;
  if(serverMode === 'online') {
    list.innerHTML = '<div id="noAccounts">Loading accounts...</div>';
    let serverUsers = null;
    try {
      const r = await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/users', {}, 4000);
      if(r.ok) serverUsers = await r.json();
    } catch(e) {}
    if(!serverUsers) {
      showServerMsg('😴 Sorry, the server is currently off. Please come again later or play Offline!');
      list.innerHTML = '<div id="noAccounts">Server unavailable — try Offline.</div>';
      return;
    }
    names  = serverUsers.map(u => u.name);
    sipFor = name => { const u = serverUsers.find(x => x.name === name); return u ? u.sip : 0; };
    // The online account list only gets {name, sip} from the server (see /api/users) — showing a
    // real picture there would mean sending every account's full picture down on every page load,
    // so this stays offline-only for now, where the picture's already sitting in localStorage for free.
    picFor = () => null;
  } else {
    names  = getUsers();
    sipFor = name => { const d = getUserData(name); return d.sip !== undefined ? d.sip : 0; };
    picFor = name => { const d = getUserData(name); return d.profilePic || null; };
  }

  if(names.length === 0) {
    list.innerHTML = '<div id="noAccounts">No accounts yet — create one below!</div>';
  } else {
    list.innerHTML = names.map(name => {
      const sip = sipFor(name).toLocaleString();
      const pic = picFor(name);
      const thumb = pic
        ? `<img src="${pic}" style="width:32px;height:32px;border-radius:6px;image-rendering:pixelated;flex-shrink:0;">`
        : '';
      return `<div class="accountCard" onclick="loginAs('${name}')">
        ${thumb}
        <div class="acInfo">
          <div class="acName">${name}</div>
          <div class="acSip">💰 ${sip} S.I.P.</div>
        </div>
        <button class="acDel" onclick="event.stopPropagation();deleteAccount('${name}')">✕</button>
      </div>`;
    }).join('');
  }
}

async function createAccount() {
  try {
    const name = document.getElementById('newAccName').value.trim();
    const pw   = document.getElementById('newAccPw').value;
    if(!name) { showBigMsg('⚠️ Enter a name first!'); return; }
    if(!pw)   { showBigMsg('⚠️ Enter a password too!'); return; }
    const pwHash = hashPassword(pw);

    if(serverMode === 'online') {
      let res;
      try {
        const r = await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/signup', {
          method: 'POST', headers: {'Content-Type':'application/json'},
          body: JSON.stringify({ name, pw: pwHash })
        }, 4000);
        res = r.ok ? await r.json() : { ok:false, error: r.status === 409 ? 'taken' : 'error' };
      } catch(e) { res = null; }
      if(!res) { showServerMsg('😴 Sorry, the server is currently off. Please come again later or play Offline!'); return; }
      if(!res.ok) { showBigMsg(res.error === 'taken' ? '⚠️ That name is taken!' : '❌ Server error, try again.'); return; }
      setPw(name, pwHash); // local cache so the same device can still log in if Offline later
      await doLogin(name);
      return;
    }

    const users = getUsers();
    if(users.includes(name)) { showBigMsg('⚠️ That name is taken!'); return; }
    users.push(name);
    saveUsers(users);
    setPw(name, pwHash);
    doLogin(name);
  } catch(e) {
    showBigMsg('❌ Error: ' + e.message);
    console.error('createAccount crash:', e);
  }
}

// Real bug report: "delete does nothing" — native confirm() is unreliable in some browsers/embeds
// (throws or is silently auto-suppressed, e.g. the itch.io iframe issue documented next to
// prompt() in game-vehicles.js; a browser can also throttle/auto-decline repeated dialogs on the
// same page). A real in-page modal (#deleteConfirmModal, EXPLOX.html) can't be silently skipped
// the same way, so deletion now goes through that instead of confirm().
let pendingDeleteAccountName = null;
function deleteAccount(name) {
  pendingDeleteAccountName = name;
  document.getElementById('deleteConfirmName').textContent = name;
  document.getElementById('deleteConfirmModal').style.display = 'flex';
}
function cancelDeleteAccount() {
  pendingDeleteAccountName = null;
  document.getElementById('deleteConfirmModal').style.display = 'none';
}
function confirmDeleteAccount() {
  const name = pendingDeleteAccountName;
  document.getElementById('deleteConfirmModal').style.display = 'none';
  pendingDeleteAccountName = null;
  if (!name) return;
  if(serverMode === 'online') {
    fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/user/' + encodeURIComponent(name), { method:'DELETE' }, 4000)
      .catch(()=>{})
      .finally(() => loadLoginScreen());
    return;
  }
  const users = getUsers().filter(u => u !== name);
  saveUsers(users);
  localStorage.removeItem('explox_user_' + name);
  localStorage.removeItem('explox_pw_' + name);
  loadLoginScreen();
}

let _pendingLogin = null;
function loginAs(name) {
  _pendingLogin = name;
  document.getElementById('pwModalName').textContent  = name;
  document.getElementById('pwModalInput').value       = '';
  document.getElementById('pwModalError').textContent = '';
  document.getElementById('pwModal').style.display    = 'flex';
  setTimeout(() => document.getElementById('pwModalInput').focus(), 50);
}
async function submitPassword() {
  const entered = document.getElementById('pwModalInput').value;
  if(!entered) {
    document.getElementById('pwModalError').textContent = '❌ Enter your password!';
    return;
  }
  const enteredHash = hashPassword(entered);

  if(serverMode === 'online') {
    let res;
    try {
      const r = await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/login', {
        method: 'POST', headers: {'Content-Type':'application/json'},
        body: JSON.stringify({ name: _pendingLogin, pw: enteredHash })
      }, 4000);
      res = r.ok ? await r.json() : { ok:false };
    } catch(e) { res = null; }
    if(!res) {
      document.getElementById('pwModal').style.display = 'none';
      showServerMsg('😴 Sorry, the server is currently off. Please come again later or play Offline!');
      return;
    }
    if(res.ok) {
      setPw(_pendingLogin, enteredHash);
      document.getElementById('pwModal').style.display = 'none';
      await doLogin(_pendingLogin);
    } else {
      document.getElementById('pwModalError').textContent = '❌ Wrong password — try again!';
      document.getElementById('pwModalInput').value = '';
      document.getElementById('pwModalInput').focus();
    }
    return;
  }

  const stored = getPw(_pendingLogin);
  let match = false;
  if(!stored) {
    setPw(_pendingLogin, enteredHash);
    match = true;
  } else {
    match = enteredHash === stored;
    if(!match && entered === stored) { match = true; setPw(_pendingLogin, enteredHash); }
  }
  if(match) {
    document.getElementById('pwModal').style.display = 'none';
    doLogin(_pendingLogin);
  } else {
    document.getElementById('pwModalError').textContent = '❌ Wrong password — try again!';
    document.getElementById('pwModalInput').value = '';
    document.getElementById('pwModalInput').focus();
  }
}
function cancelPassword() {
  document.getElementById('pwModal').style.display = 'none';
  _pendingLogin = null;
}

async function doLogin(name) {
  if(serverMode === 'online') {
    // Pull the server's copy into localStorage first, so the rest of this
    // function (and every other place in the game that reads getUserData)
    // works completely unchanged, whether we're online or offline.
    try {
      const r = await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/user/' + encodeURIComponent(name), {}, 4000);
      if(r.ok) localStorage.setItem('explox_user_' + name, JSON.stringify(await r.json()));
    } catch(e) { /* no save on the server yet, or it dropped mid-fetch — fall back to local copy */ }
  }
  currentUser = name;
  refreshAdminTabVisibility(); // "commands only for me" — shows the ADMIN tab only for ADMIN_ACCOUNTS (game-admin.js)
  const d = getUserData(name);
  // A genuinely brand-new account (never saved before) starts growth at 0 (Baby) — that's the
  // whole point of the feature. An EXISTING account just updated to a version with growth added
  // has no playTimeSeconds field either, but already has other real fields (sip, wood, ...) —
  // defaulting THAT case to 1800 (Adult) avoids visually shrinking an established character.
  const isBrandNewAccount = Object.keys(d).length === 0;
  playTimeSeconds = d.playTimeSeconds !== undefined ? d.playTimeSeconds : (isBrandNewAccount ? 0 : 1800);
  lastGrowthStageId = d.lastGrowthStageId || growthStageFor(playTimeSeconds).id;
  eliteCoins = d.eliteCoins !== undefined ? d.eliteCoins : 0;
  playerHat   = d.hat   || 'none';    playerHair  = d.hair  || 'none';
  playerShirt = d.shirt || 'plain';   playerPants = d.pants || 'long';
  playerShoes = d.shoes || 'sneakers';
  playerColors = {
    skin:  d.skin       || '#f5c89a',
    shirt: d.shirtColor || '#2196F3',
    pants: d.pantsColor || '#333333',
    shoes: d.shoesColor || '#4e3b2a',
    hair:  d.hairColor  || '#3a1f0a'
  };
  playerName    = d.name         || name;
  playerProfilePic = d.profilePic || null;
  playerShirtPaint = d.shirtPaint || null;
  sipDollars    = d.sip !== undefined ? d.sip : 0;
  cash          = d.cash !== undefined ? d.cash : 0; // Cash/ATM feature — physical cash carried, separate from bank-safe sipDollars
  woodCount     = d.wood !== undefined ? d.wood : 0;
  scrapMetal    = d.scrap !== undefined ? d.scrap : 0;
  ownedLand     = Array.isArray(d.ownedLand) ? d.ownedLand : [];
  plotBuildings = d.plotBuildings && typeof d.plotBuildings === 'object' ? d.plotBuildings : {};
  landInvites   = d.landInvites  && typeof d.landInvites  === 'object' ? d.landInvites  : {};
  landColor     = d.landColor    && typeof d.landColor    === 'object' ? d.landColor    : {};
  landForSale   = d.landForSale  && typeof d.landForSale  === 'object' ? d.landForSale  : {};
  pendingNotices = Array.isArray(d.pendingNotices) ? d.pendingNotices : [];
  tubeLikes = d.tubeLikes && typeof d.tubeLikes === 'object' ? d.tubeLikes : {};
  tubeViews = d.tubeViews && typeof d.tubeViews === 'object' ? d.tubeViews : {};
  tubeBaseComments = d.tubeBaseComments && typeof d.tubeBaseComments === 'object' ? d.tubeBaseComments : {};
  myUploads = Array.isArray(d.myUploads) ? d.myUploads : [];
  mySubscribers = d.mySubscribers !== undefined ? d.mySubscribers : 0;
  carLocation = d.carLocation || 'Downtown Explox';
  installedApps = Array.isArray(d.installedApps) ? d.installedApps : [];
  bankBalance     = d.bankBalance !== undefined ? d.bankBalance : 0;
  bankEliteBalance = d.bankEliteBalance !== undefined ? d.bankEliteBalance : BANK_VAULT_ELITE_SEED;
  playerInventory = d.inventory && typeof d.inventory === 'object' ? d.inventory : {};
  for (const invId of Object.keys(playerInventory)) {
    const it = playerInventory[invId];
    if (!it || typeof it !== 'object' || typeof it.name !== 'string' || typeof it.emoji !== 'string' || typeof it.qty !== 'number') {
      delete playerInventory[invId];
    }
  }
  playerBirthday = d.birthday || '';
  setBirthdayDropdowns(playerBirthday);
  safeBalance     = d.safeBalance    || 0;
  safeCombo       = d.safeCombo      || null;
  safeInventory   = d.safeInventory  || null;
  trashSafeCombo  = d.trashSafeCombo || null;
  trashSafeSip    = d.trashSafeSip   || 0;
  trashSafeItems  = d.trashSafeItems || {};
  playerWeapon  = d.weapon       || 'none';
  ownedWeapons  = d.ownedWeapons || [];
  playerArmor   = d.armor        || 'none';
  ownedArmor    = d.ownedArmor   || [];
  ownedItems    = d.ownedItems   || [];
  ownedSkins    = d.ownedSkins   || [];
  alignment     = d.alignment    || 'good';
  wantedLevel   = d.wanted      || 0;
  ownedCars     = d.ownedCars     || [];
  ownedComputers = d.ownedComputers || [];
  ownedStore    = d.ownedStore    || null;
  ownedFurniture = d.ownedFurniture || [];
  ownedHouseFurniture = d.ownedHouseFurniture || [];
  storeStock = d.storeStock && typeof d.storeStock === 'object' ? d.storeStock : {};
  storePrices = d.storePrices && typeof d.storePrices === 'object' ? d.storePrices : {};
  storeSalesCount = d.storeSalesCount !== undefined ? d.storeSalesCount : 0;
  storeStockOrder = Array.isArray(d.storeStockOrder) ? d.storeStockOrder : [];
  storeAdLevel = d.storeAdLevel !== undefined ? d.storeAdLevel : 0;
  ownedStaff = Array.isArray(d.ownedStaff) ? d.ownedStaff : [];
  friends = Array.isArray(d.friends) ? d.friends : [];
  houseGuest = d.houseGuest || null;
  marriages = Array.isArray(d.marriages) ? d.marriages : [];
  children = Array.isArray(d.children) ? d.children : [];
  elderLifespans = d.elderLifespans && typeof d.elderLifespans === 'object' ? d.elderLifespans : {};
  elderPassed = d.elderPassed && typeof d.elderPassed === 'object' ? d.elderPassed : {};
  lastBirthdayGiftDate = d.lastBirthdayGiftDate || '';
  deadNPCs = d.deadNPCs && typeof d.deadNPCs === 'object' ? d.deadNPCs : {};
  buddyOwned   = !!d.buddyOwned;
  buddySpecies = d.buddySpecies || null;
  buddyName    = d.buddyName || 'Buddy';
  buddyColors  = d.buddyColors && typeof d.buddyColors === 'object' ? d.buddyColors : { body:'#66ddff', accent:'#ffffff', eye:'#111111' };
  activeAddOns = Array.isArray(d.activeAddOns) ? d.activeAddOns : [];
  familyKidAdopted = !!d.familyKidAdopted;
  familyKidId   = d.familyKidId || null;
  familyKidName    = d.familyKidName || 'Kiddo';
  familyKidPlayTime = d.familyKidPlayTime !== undefined ? d.familyKidPlayTime : 0;
  familyKidInSchool = !!d.familyKidInSchool;
  familyKidSmarts   = d.familyKidSmarts !== undefined ? d.familyKidSmarts : 0;
  familyKidLastStageId = d.familyKidLastStageId || growthStageFor(familyKidPlayTime).id;
  lastAllowanceAt = d.lastAllowanceAt !== undefined ? d.lastAllowanceAt : -999;
  unpaidBills   = Array.isArray(d.unpaidBills) ? d.unpaidBills : [];
  lastBillCheck = d.lastBillCheck !== undefined ? d.lastBillCheck : playTimeSeconds;
  // Same brand-new-vs-existing-account distinction as playTimeSeconds above: a genuinely new
  // account has never seen the guide (show it); an existing account predating this feature
  // shouldn't suddenly get nagged with it on their next login.
  hasSeenGuide = d.hasSeenGuide !== undefined ? !!d.hasSeenGuide : !isBrandNewAccount;
  hasBusinessLicense = !!d.hasBusinessLicense; // City Hall Forms Office — game-shops.js
  businessLicenseInfo = d.businessLicenseInfo && typeof d.businessLicenseInfo === 'object' ? d.businessLicenseInfo : null;
  approvedPermits = Array.isArray(d.approvedPermits) ? d.approvedPermits : [];
  myStocks = d.myStocks && typeof d.myStocks === 'object' ? d.myStocks : {};
  ffaKills = d.ffaKills !== undefined ? d.ffaKills : 0;
  eatingCompBests = d.eatingCompBests && typeof d.eatingCompBests === 'object' ? d.eatingCompBests : {};
  eliteLevel = d.eliteLevel !== undefined ? d.eliteLevel : 0;
  // Recomputed here (not left at the module-load default of 100) so a login always starts fresh
  // at the CORRECT full health for this account's real Robot Level, not last account's or nobody's.
  playerMaxHealth = computePlayerMaxHealth();
  playerHealth = playerMaxHealth;
  hunger = 100; _starveDamageAt = 0; // same "always start this session full" treatment as health above
  sick = false; sickUntil = 0; _sickCheckAt = 0; _sickDamageAt = 0;
  updateSickHud();
  bladder = 100; embarrassedUntil = 0;
  updateBladderHud();
  tiredness = 100; exhaustedSince = 0;
  updateTirednessHud();
  activeQuests = Array.isArray(d.activeQuests) ? d.activeQuests : [];
  lifetimeRobotKills = d.lifetimeRobotKills !== undefined ? d.lifetimeRobotKills : 0;
  lifetimeRogueKills = d.lifetimeRogueKills !== undefined ? d.lifetimeRogueKills : 0;
  lifetimeWarHits    = d.lifetimeWarHits !== undefined ? d.lifetimeWarHits : 0;
  killerDefeats      = d.killerDefeats !== undefined ? d.killerDefeats : 0;
  totalKills         = d.totalKills !== undefined ? d.totalKills : 0;
  wrathTriggerCount  = d.wrathTriggerCount !== undefined ? d.wrathTriggerCount : 0;
  divineJudgmentServed = !!d.divineJudgmentServed; // persisted — once true, this can never fire again on this account
  divineSentenceStartedAt = d.divineSentenceStartedAt !== undefined ? d.divineSentenceStartedAt : 0;
  divineRedemptionGranted = !!d.divineRedemptionGranted;
  lastSatanBossFightAt = d.lastSatanBossFightAt !== undefined ? d.lastSatanBossFightAt : 0;
  lastEventOfDayClaim = d.lastEventOfDayClaim !== undefined ? d.lastEventOfDayClaim : '';
  dailyStreakCount = d.dailyStreakCount !== undefined ? d.dailyStreakCount : 0;
  lastStreakClaimDate = d.lastStreakClaimDate !== undefined ? d.lastStreakClaimDate : '';
  churchLastPrayed   = d.churchLastPrayed !== undefined ? d.churchLastPrayed : 0;
  safePeriodEndsAt   = d.safePeriodEndsAt !== undefined ? d.safePeriodEndsAt : 0;
  schoolLastQuizAt   = d.schoolLastQuizAt !== undefined ? d.schoolLastQuizAt : 0; // real School day cooldown gate — see SCHOOL_QUIZ_COOLDOWN_MS, game-land.js
  schoolVisitCount   = d.schoolVisitCount !== undefined ? d.schoolVisitCount : 0; // real school days STARTED — every 10th is an exam day, game-land.js
  schoolHomework     = d.schoolHomework && typeof d.schoolHomework === 'object' ? d.schoolHomework : null; // real pending homework — {subject, bandId}, game-land.js
  if (document.getElementById('homeworkTab')) document.getElementById('homeworkTab').style.display = schoolHomework ? 'block' : 'none';
  // Unlike the old satanBadUntil (a short mid-chase timer that deliberately didn't survive
  // reload), Satan's Reign is a real ongoing world takeover now — a page reload shouldn't let
  // players dodge an active reign or lose real progress made pushing back against it (see
  // SATAN_REIGN_GOAL in game-world.js), so it's restored here the same way safePeriodEndsAt above
  // already is.
  satanReignActive    = !!d.satanReignActive;
  satanReignProgress  = d.satanReignProgress !== undefined ? d.satanReignProgress : 0;
  satanReignStartedAt = d.satanReignStartedAt !== undefined ? d.satanReignStartedAt : 0;
  wrathActive = false; satanCheckTimer = 0; // a fresh login always starts with no mid-chase state — Wrath is a personal chase, not shared world state
  // max()'d against the account's real current balance so an account that already had money
  // before this feature existed shows a correct record immediately, not a jarring 0.
  peakSip  = Math.max(d.peakSip !== undefined ? d.peakSip : 0, sipDollars);
  peakElite = Math.max(d.peakElite !== undefined ? d.peakElite : 0, eliteCoins);
  totalQuestsCompleted = d.totalQuestsCompleted !== undefined ? d.totalQuestsCompleted : 0;
  totalBossesDefeated  = d.totalBossesDefeated !== undefined ? d.totalBossesDefeated : 0;
  pendingEarnings    = Array.isArray(d.pendingEarnings) ? d.pendingEarnings : [];
  _earningsOverdueNotified = new Set(); // fresh per login — a still-overdue earning just nags again once, not a bug
  updateEarningsBadge();
  ensureQuests();
  activeContracts = Array.isArray(d.activeContracts) ? d.activeContracts : [];
  lifetimeShopsRobbed = d.lifetimeShopsRobbed !== undefined ? d.lifetimeShopsRobbed : 0;
  lifetimeCitizensDefeated = d.lifetimeCitizensDefeated !== undefined ? d.lifetimeCitizensDefeated : 0;
  lifetimeCopsDefeated = d.lifetimeCopsDefeated !== undefined ? d.lifetimeCopsDefeated : 0;
  totalContractsCompleted = d.totalContractsCompleted !== undefined ? d.totalContractsCompleted : 0;
  calendarReminders = Array.isArray(d.calendarReminders) ? d.calendarReminders : [];
  spyLocationTally  = d.spyLocationTally && typeof d.spyLocationTally === 'object' ? d.spyLocationTally : {};
  spyFavoriteSpot   = d.spyFavoriteSpot || null;
  spyDiscoveredAt   = d.spyDiscoveredAt !== undefined ? d.spyDiscoveredAt : 0;
  spyNextEligibleAt = d.spyNextEligibleAt !== undefined ? d.spyNextEligibleAt : 0;
  // Mysteries (game-world.js) — real detective cases that trigger on their own. A brand-new
  // account (and any existing account predating this feature, since d.mysteryNextTriggerAt is
  // undefined either way) gets its first possible case scheduled 5-10 real minutes from THIS
  // login, same range tickMysteries() uses between every later case — no instant case on login,
  // but no long silent wait either.
  mysteryCaseState    = d.mysteryCaseState && typeof d.mysteryCaseState === 'object' ? d.mysteryCaseState : {};
  mysteryActiveCaseId = d.mysteryActiveCaseId || null;
  mysteryNextTriggerAt = d.mysteryNextTriggerAt !== undefined ? d.mysteryNextTriggerAt : (Date.now() + MYSTERY_TRIGGER_MIN_MS + Math.random()*(MYSTERY_TRIGGER_MAX_MS-MYSTERY_TRIGGER_MIN_MS));
  if (alignment === 'bad') ensureContracts();
  shopOpen = false; // never resume a shop as open across a reload — you have to reopen it yourself
  document.getElementById('skinColor').value  = playerColors.skin;
  document.getElementById('shirtColor').value = playerColors.shirt;
  document.getElementById('pantsColor').value = playerColors.pants;
  document.getElementById('shoeColor').value  = playerColors.shoes;
  document.getElementById('hairColor').value  = playerColors.hair;
  document.getElementById('nameInput').value  = playerName;
  setBtn('hatBtns',   playerHat);
  setBtn('hairBtns',  playerHair);
  setBtn('shirtBtns', playerShirt);
  setBtn('pantsBtns', playerPants);
  setBtn('shoeBtns',  playerShoes);
  localStorage.setItem('explox_current_user', currentUser);
  document.getElementById('loginScreen').style.display  = 'none';
  document.getElementById('customScreen').style.display = 'flex';
  document.getElementById('customSip').textContent = sipDollars;
  refreshItemLocks();
  renderSkinsSection();
  if(document.getElementById('alignmentHud')) {
    document.getElementById('alignmentHud').style.display = alignment==='bad' ? 'block' : 'none';
  }
  if(document.getElementById('contractsTab')) {
    document.getElementById('contractsTab').style.display = alignment==='bad' ? 'block' : 'none';
  }
  if(document.getElementById('wantedHud')) updateWantedHud();
  refreshPreviews();
  setTimeout(refreshPreviews, 50);
}

function fillBdDays(month, selectedDay) {
  const sel = document.getElementById('bdDay');
  if(!sel) return;
  const days = [31,28,31,30,31,30,31,31,30,31,30,31];
  const count = month ? days[parseInt(month)-1] : 31;
  sel.innerHTML = '<option value="">Day</option>';
  for(let d=1; d<=count; d++) {
    const val = String(d).padStart(2,'0');
    sel.innerHTML += `<option value="${val}"${val===selectedDay?' selected':''}>${d}</option>`;
  }
}
function setBirthdayDropdowns(mmdd) {
  if(!mmdd) return;
  const [mm, dd] = mmdd.split('-');
  const mSel = document.getElementById('bdMonth');
  if(mSel) mSel.value = mm;
  fillBdDays(mm, dd);
}

function showMsg(txt) {
  const m = document.getElementById('loginMsg');
  m.textContent = txt;
  m.style.fontSize = '15px';
  m.style.fontWeight = 'bold';
  m.style.color = '#ff4444';
  setTimeout(() => m.textContent = '', 3000);
}

function showBigMsg(txt) {
  let box = document.getElementById('bigMsgBox');
  if(!box) {
    box = document.createElement('div');
    box.id = 'bigMsgBox';
    box.style.cssText = 'position:fixed;top:30px;left:50%;transform:translateX(-50%);background:#c0392b;color:#fff;font-size:18px;font-weight:bold;padding:16px 32px;border-radius:12px;z-index:9999;text-align:center;box-shadow:0 4px 20px rgba(0,0,0,0.5);';
    document.body.appendChild(box);
  }
  box.textContent = txt;
  box.style.display = 'block';
  clearTimeout(box._t);
  box._t = setTimeout(() => box.style.display = 'none', 3000);
}

// ─── BANK ────────────────────────────────────────────────────────────────────
const BANK_PASSCODE = 'cubbyexplotionisthebest';

function openBankPasscode() {
  if(document.pointerLockElement) document.exitPointerLock();
  isPointerLocked = false;
  document.getElementById('bankPcInput').value = '';
  document.getElementById('bankPcError').textContent = '';
  document.getElementById('bankPasscodeModal').style.display = 'flex';
  setTimeout(() => document.getElementById('bankPcInput').focus(), 50);
}
function submitBankPasscode() {
  const entered = document.getElementById('bankPcInput').value;
  if(entered === BANK_PASSCODE) {
    document.getElementById('bankPasscodeModal').style.display = 'none';
    openBank();
  } else {
    document.getElementById('bankPcError').textContent = 'Wrong passcode! Access denied.';
    document.getElementById('bankPcInput').value = '';
    document.getElementById('bankPcInput').focus();
  }
}
// Skips the shared City Bank passcode entirely and goes straight to the player's
// OWN account — the existing Safe feature (its own balance, its own combo the
// player sets themselves, nothing to do with the shared BANK_PASSCODE).
function openMyOwnAccount() {
  document.getElementById('bankPasscodeModal').style.display = 'none';
  openSafeModal();
}
function cancelBankPasscode() {
  document.getElementById('bankPasscodeModal').style.display = 'none';
  if(renderer && renderer.domElement) renderer.domElement.requestPointerLock();
}

// ─── SAFE ────────────────────────────────────────────────────────────────────
function openSafeModal() {
  const modal = document.getElementById('safeModal');
  modal.style.display = 'flex';
  document.getElementById('safeSetView').style.display   = safeCombo ? 'none'  : 'block';
  document.getElementById('safeEnterView').style.display = safeCombo ? 'block' : 'none';
  document.getElementById('safeOpenView').style.display  = 'none';
  if(!safeCombo) {
    document.getElementById('safeNewCombo').value     = '';
    document.getElementById('safeConfirmCombo').value = '';
    document.getElementById('safeSetErr').textContent  = '';
    setTimeout(() => document.getElementById('safeNewCombo').focus(), 50);
  } else {
    document.getElementById('safeComboInput').value    = '';
    document.getElementById('safeEnterErr').textContent = '';
    setTimeout(() => document.getElementById('safeComboInput').focus(), 50);
  }
}

function setSafeCombo() {
  const c1  = document.getElementById('safeNewCombo').value;
  const c2  = document.getElementById('safeConfirmCombo').value;
  const err = document.getElementById('safeSetErr');
  if(!c1)      { err.textContent = 'Enter a combo!';          return; }
  if(c1 !== c2){ err.textContent = "Combos don't match!";    return; }
  safeCombo = c1;
  saveCurrentUser();
  document.getElementById('safeSetView').style.display = 'none';
  showSafeOpen();
}

function submitSafeCombo() {
  const entered = document.getElementById('safeComboInput').value;
  if(entered === safeCombo) {
    document.getElementById('safeEnterView').style.display = 'none';
    showSafeOpen();
  } else {
    document.getElementById('safeEnterErr').textContent = 'Wrong combo! Try again.';
    document.getElementById('safeComboInput').value = '';
    document.getElementById('safeComboInput').focus();
  }
}

const MINI_GAME_WEAPONS = [
  { id:'mg_laser_sword',    name:'Laser Sword',    emoji:'⚡' },
  { id:'mg_plasma_blaster', name:'Plasma Blaster', emoji:'🔴' },
  { id:'mg_scatter_blast',  name:'Scatter Blast',  emoji:'💥' },
  { id:'mg_ghost_blade',    name:'Ghost Blade',    emoji:'👻' },
  { id:'mg_flame_sword',    name:'Flame Sword',    emoji:'🔥' },
  { id:'mg_cryo_cannon',    name:'Cryo Cannon',    emoji:'❄️' },
  { id:'mg_seeker_missile', name:'Seeker Missile', emoji:'🚀' },
  { id:'mg_void_arrow',     name:'Void Arrow',     emoji:'🌑' },
  { id:'mg_thunder_staff',  name:'Thunder Staff',  emoji:'🌩️' },
  { id:'mg_titan_fist',     name:'Titan Fist',     emoji:'👊' },
];

function initSafeInventory() {
  safeInventory = {};
  Object.entries(ITEM_INFO).forEach(([name, info]) => {
    safeInventory[info.id] = { name, emoji: info.emoji, qty: 1 };
  });
  MINI_GAME_WEAPONS.forEach(w => {
    safeInventory[w.id] = { name: w.name, emoji: w.emoji, qty: 1 };
  });
}

function refreshSafeItems() {
  const el = document.getElementById('safeItemsList');
  if(!el) return;
  const keys = Object.keys(safeInventory || {});
  if(keys.length === 0) {
    el.innerHTML = '<div style="color:#555;font-size:11px;text-align:center;padding:8px 0;">Safe items empty</div>';
    return;
  }
  el.innerHTML = '<div style="color:#886600;font-size:10px;letter-spacing:1px;margin-bottom:6px;">ITEMS IN SAFE</div>' +
    keys.map(id => {
      const it = safeInventory[id];
      return `<div style="display:flex;align-items:center;gap:8px;background:rgba(255,215,0,0.06);border:1px solid #443300;border-radius:6px;padding:6px 10px;margin-bottom:5px;">
        <span style="font-size:18px;">${it.emoji}</span>
        <span style="flex:1;color:#fff;font-size:12px;">${it.name}</span>
        <button onclick="takeFromSafe('${id}')" style="padding:3px 10px;background:#1a3a1a;border:1px solid #44aa44;border-radius:5px;color:#44ff88;font-size:11px;cursor:pointer;font-weight:bold;">Take</button>
      </div>`;
    }).join('');
}

function takeFromSafe(id) {
  if(!safeInventory || !safeInventory[id]) return;
  const it = safeInventory[id];
  addToInventory(id, it.name, it.emoji);
  delete safeInventory[id];
  saveCurrentUser();
  refreshSafeItems();
  const msg = document.getElementById('safeMsg');
  msg.style.color = '#44ff88';
  msg.textContent = '✅ Took ' + it.emoji + ' ' + it.name + ' into your bag!';
}

function showSafeOpen() {
  if(!safeInventory) initSafeInventory();
  document.getElementById('safeWalletDisplay').textContent = sipDollars.toLocaleString() + ' S.I.P.';
  document.getElementById('safeBalDisplay').textContent    = safeBalance.toLocaleString() + ' S.I.P.';
  document.getElementById('safeAmtInput').value = '';
  document.getElementById('safeMsg').textContent = '';
  document.getElementById('safeOpenView').style.display = 'block';
  refreshSafeItems();
}

function closeSafe() {
  document.getElementById('safeModal').style.display = 'none';
}

function safeDeposit() {
  const amt = parseInt(document.getElementById('safeAmtInput').value);
  const msg = document.getElementById('safeMsg');
  if(!amt || amt <= 0)  { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!';    return; }
  if(amt > sipDollars)  { msg.style.color='#ff8888'; msg.textContent="You don't have that much!"; return; }
  sipDollars  -= amt;
  safeBalance += amt;
  document.getElementById('sipAmount').textContent         = sipDollars;
  document.getElementById('safeWalletDisplay').textContent = sipDollars.toLocaleString()  + ' S.I.P.';
  document.getElementById('safeBalDisplay').textContent    = safeBalance.toLocaleString() + ' S.I.P.';
  msg.style.color = '#44ff88';
  msg.textContent = '✅ Locked in ' + amt.toLocaleString() + ' S.I.P.!';
  saveCurrentUser();
}

function safeWithdraw() {
  const amt = parseInt(document.getElementById('safeAmtInput').value);
  const msg = document.getElementById('safeMsg');
  if(!amt || amt <= 0)  { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!';    return; }
  if(amt > safeBalance) { msg.style.color='#ff8888'; msg.textContent='Not enough in the safe!'; return; }
  safeBalance -= amt;
  sipDollars  += amt;
  document.getElementById('sipAmount').textContent         = sipDollars;
  document.getElementById('safeWalletDisplay').textContent = sipDollars.toLocaleString()  + ' S.I.P.';
  document.getElementById('safeBalDisplay').textContent    = safeBalance.toLocaleString() + ' S.I.P.';
  msg.style.color = '#FFD700';
  msg.textContent = '✅ Took out ' + amt.toLocaleString() + ' S.I.P.!';
  saveCurrentUser();
}

// ─── TRASH SAFE — "add a trash safe you set a passcode others can't get it but can put stuff in
// the same trash can so you can put your stuff in". Two halves, deliberately asymmetric: GIVING
// needs no passcode at all (anyone, including you, can put something in — via sendMail() to a
// named account, same real cross-machine delivery the S.I.P./prayer gifts already use), but
// OPENING it to see or take anything back out is passcode-gated exactly like the existing
// per-account Safe above, just a second, separate combo.
function openTrashModal() {
  if(document.pointerLockElement) document.exitPointerLock();
  isPointerLocked = false;
  document.getElementById('trashModal').style.display = 'flex';
  trashShowGiveView();
}
function closeTrashModal() {
  document.getElementById('trashModal').style.display = 'none';
  if(renderer && renderer.domElement) renderer.domElement.requestPointerLock();
}
function trashShowGiveView() {
  document.getElementById('trashGiveView').style.display = 'block';
  document.getElementById('trashSafeSetView').style.display = 'none';
  document.getElementById('trashSafeEnterView').style.display = 'none';
  document.getElementById('trashSafeOpenView').style.display = 'none';
  document.getElementById('trashGiveTarget').value = '';
  document.getElementById('trashGiveItem').value = '';
  document.getElementById('trashGiveSip').value = '';
  document.getElementById('trashGiveMsg').textContent = '';
}
function trashShowMySafe() {
  document.getElementById('trashGiveView').style.display = 'none';
  document.getElementById('trashSafeOpenView').style.display = 'none';
  if(!trashSafeCombo) {
    document.getElementById('trashSafeSetView').style.display = 'block';
    document.getElementById('trashSafeEnterView').style.display = 'none';
    document.getElementById('trashSafeNewCombo').value = '';
    document.getElementById('trashSafeConfirmCombo').value = '';
    document.getElementById('trashSafeSetErr').textContent = '';
  } else {
    document.getElementById('trashSafeSetView').style.display = 'none';
    document.getElementById('trashSafeEnterView').style.display = 'block';
    document.getElementById('trashSafeComboInput').value = '';
    document.getElementById('trashSafeEnterErr').textContent = '';
  }
}
function setTrashSafeCombo() {
  const c1 = document.getElementById('trashSafeNewCombo').value;
  const c2 = document.getElementById('trashSafeConfirmCombo').value;
  const err = document.getElementById('trashSafeSetErr');
  if(!c1)       { err.textContent = 'Enter a passcode!';        return; }
  if(c1 !== c2) { err.textContent = "Passcodes don't match!";  return; }
  trashSafeCombo = c1;
  saveCurrentUser();
  document.getElementById('trashSafeSetView').style.display = 'none';
  trashShowSafeOpen();
}
function submitTrashSafeCombo() {
  const entered = document.getElementById('trashSafeComboInput').value;
  if(entered === trashSafeCombo) {
    document.getElementById('trashSafeEnterView').style.display = 'none';
    trashShowSafeOpen();
  } else {
    document.getElementById('trashSafeEnterErr').textContent = 'Wrong passcode! Try again.';
    document.getElementById('trashSafeComboInput').value = '';
  }
}
function trashShowSafeOpen() {
  document.getElementById('trashSafeOpenView').style.display = 'block';
  document.getElementById('trashSafeSipDisplay').textContent = trashSafeSip.toLocaleString() + ' S.I.P.';
  refreshTrashSafeItems();
}
function refreshTrashSafeItems() {
  const el = document.getElementById('trashSafeItemsList');
  if(!el) return;
  const keys = Object.keys(trashSafeItems || {});
  if(keys.length === 0) {
    el.innerHTML = '<div style="color:#555;font-size:11px;text-align:center;padding:8px 0;">Nothing in here yet</div>';
    return;
  }
  el.innerHTML = keys.map(id => {
    const it = trashSafeItems[id];
    return `<div style="display:flex;align-items:center;gap:8px;background:rgba(120,255,120,0.06);border:1px solid #335533;border-radius:6px;padding:6px 10px;margin-bottom:5px;">
      <span style="font-size:18px;">${it.emoji}</span>
      <span style="flex:1;color:#fff;font-size:12px;">${it.name}${it.qty > 1 ? ` x${it.qty}` : ''}</span>
      <button onclick="takeFromTrashSafe('${id}')" style="padding:3px 10px;background:#1a3a1a;border:1px solid #44aa44;border-radius:5px;color:#44ff88;font-size:11px;cursor:pointer;font-weight:bold;">Take</button>
    </div>`;
  }).join('');
}
function takeFromTrashSafe(id) {
  const it = trashSafeItems[id];
  if(!it) return;
  for(let i = 0; i < it.qty; i++) addToInventory(id, it.name, it.emoji);
  delete trashSafeItems[id];
  saveCurrentUser();
  refreshTrashSafeItems();
}
function withdrawTrashSafeSip() {
  if(trashSafeSip <= 0) return;
  sipDollars += trashSafeSip;
  updateSIP();
  trashSafeSip = 0;
  saveCurrentUser();
  trashShowSafeOpen();
}
function depositIntoOwnTrashSafe(id, name, emoji, qty) {
  if(trashSafeItems[id]) trashSafeItems[id].qty += qty; else trashSafeItems[id] = { name, emoji, qty };
  saveCurrentUser();
}
function trashGiveItem() {
  const target = document.getElementById('trashGiveTarget').value.trim() || currentUser;
  const query = document.getElementById('trashGiveItem').value.trim().toLowerCase();
  const msg = document.getElementById('trashGiveMsg');
  if(!query) { msg.style.color = '#ff8888'; msg.textContent = 'Type an item name!'; return; }
  if(target !== currentUser && serverMode !== 'online') { msg.style.color = '#ff8888'; msg.textContent = 'Giving to someone else needs ONLINE mode!'; return; }
  const entry = Object.entries(playerInventory).find(([id, it]) => it.name.toLowerCase().includes(query));
  if(!entry) { msg.style.color = '#ff8888'; msg.textContent = "You don't have that item!"; return; }
  const [id, it] = entry;
  const name = it.name, emoji = it.emoji;
  it.qty--;
  if(it.qty <= 0) delete playerInventory[id];
  saveCurrentUser();
  if(target === currentUser) {
    depositIntoOwnTrashSafe(id, name, emoji, 1);
    msg.style.color = '#44ff88'; msg.textContent = `✅ Put ${emoji} ${name} in your Trash Safe!`;
  } else {
    sendMail(target, 'trash_deposit', { kind: 'item', id, name, emoji, qty: 1 });
    msg.style.color = '#44ff88'; msg.textContent = `✅ Sent ${emoji} ${name} to ${target}'s Trash Safe!`;
  }
  document.getElementById('trashGiveItem').value = '';
}
function trashGiveSip() {
  const target = document.getElementById('trashGiveTarget').value.trim() || currentUser;
  const amt = parseInt(document.getElementById('trashGiveSip').value, 10);
  const msg = document.getElementById('trashGiveMsg');
  if(!Number.isFinite(amt) || amt <= 0) { msg.style.color = '#ff8888'; msg.textContent = 'Enter a valid amount!'; return; }
  if(amt > sipDollars) { msg.style.color = '#ff8888'; msg.textContent = "You don't have that much!"; return; }
  if(target !== currentUser && serverMode !== 'online') { msg.style.color = '#ff8888'; msg.textContent = 'Giving to someone else needs ONLINE mode!'; return; }
  sipDollars -= amt; updateSIP();
  if(target === currentUser) {
    trashSafeSip += amt; saveCurrentUser();
    msg.style.color = '#44ff88'; msg.textContent = `✅ Put ${amt.toLocaleString()} S.I.P. in your Trash Safe!`;
  } else {
    sendMail(target, 'trash_deposit', { kind: 'sip', amount: amt });
    msg.style.color = '#44ff88'; msg.textContent = `✅ Sent ${amt.toLocaleString()} S.I.P. to ${target}'s Trash Safe!`;
  }
  document.getElementById('trashGiveSip').value = '';
}

function openBank() {
  document.getElementById('bankWalletDisplay').textContent = sipDollars.toLocaleString() + ' S.I.P.';
  document.getElementById('bankBalDisplay').textContent = bankBalance.toLocaleString() + ' S.I.P.';
  document.getElementById('bankAmtInput').value = '';
  document.getElementById('bankEliteWalletDisplay').textContent = Math.floor(eliteCoins).toLocaleString() + ' 💎';
  document.getElementById('bankEliteBalDisplay').textContent = formatBigNum(bankEliteBalance) + ' 💎';
  document.getElementById('bankEliteAmtInput').value = '';
  // Cash/ATM feature — display-only here (an ATM is where you actually move money between this
  // and sipDollars); still worth showing while you're at the Bank so you can see your full real
  // financial picture in one place, same reason the Diamond Wallet sits in this same overlay.
  const bcd = document.getElementById('bankCashDisplay');
  if (bcd) bcd.textContent = '$' + Math.floor(cash).toLocaleString();
  document.getElementById('bankMsg').textContent = '';
  document.getElementById('bankOverlay').style.display = 'flex';
}
function closeBank() {
  document.getElementById('bankOverlay').style.display = 'none';
  if(renderer && renderer.domElement) renderer.domElement.requestPointerLock();
}

// ─── STOCK MARKET — real shared prices, same for every online player ────────
const STOCK_DEFS = [
  { symbol:'CUBY', name:'Cubby Corp',        emoji:'🏢' },
  { symbol:'EXPL', name:'Explox Industries', emoji:'🏭' },
  { symbol:'ROBO', name:'RoboWorks',         emoji:'🤖' },
  { symbol:'SNAK', name:'Snack Co',          emoji:'🍿' },
  { symbol:'CARZ', name:'CarZone',           emoji:'🚗' },
  { symbol:'GAME', name:'GameSphere',        emoji:'🎮' },
];
let stockPrices = {}; // symbol -> price, synced from the server - same for everyone online
let myStocks = {};    // symbol -> shares owned, personal, persisted like everything else
let _lastStockSync = -999;
const STOCK_SYNC_INTERVAL = 5;
async function syncStocks() {
  if(serverMode !== 'online') return;
  try {
    const r = await fetchWithTimeout(EXPLOX_ONLINE_URL + '/api/stocks', {}, 4000);
    if(r.ok) { stockPrices = await r.json(); refreshStockMarketUI(); }
  } catch(e) { /* next sync will catch up */ }
}

function openStockMarket() {
  document.getElementById('stockMarketModal').style.display = 'flex';
  refreshStockMarketUI();
}
function closeStockMarket() {
  document.getElementById('stockMarketModal').style.display = 'none';
}
function refreshStockMarketUI() {
  const list = document.getElementById('stockMarketList');
  if(!list || document.getElementById('stockMarketModal').style.display === 'none') return;
  if(serverMode !== 'online') {
    list.innerHTML = '<div style="color:#888;text-align:center;padding:20px;font-size:12px;">📡 The Stock Market needs you to be ONLINE.<br>Go back to the account screen and click ONLINE first.</div>';
    return;
  }
  if(Object.keys(stockPrices).length === 0) {
    list.innerHTML = '<div style="color:#888;text-align:center;padding:20px;font-size:12px;">Loading real-time prices...</div>';
    return;
  }
  list.innerHTML = STOCK_DEFS.map(def => {
    const price = stockPrices[def.symbol] || 0;
    const owned = myStocks[def.symbol] || 0;
    return `<div class="shopItem">
      <div class="siName">${def.emoji} ${def.name} <span style="color:#888;">(${def.symbol})</span></div>
      <div class="siCost">💰 ${price.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})} S.I.P./share${owned ? ` — you own ${owned}` : ''}</div>
      <div style="display:flex;gap:6px;">
        <button class="shopBtn" onclick="buyStockShares('${def.symbol}')">Buy 1</button>
        ${owned > 0 ? `<button class="shopBtn" onclick="sellStockShares('${def.symbol}')" style="background:#4a1a1a;">Sell 1</button>` : ''}
      </div>
    </div>`;
  }).join('');
}
// Every real S.I.P. payment anywhere in the game (shops, add-ons, bills, land, cars, food,
// clothes, everything) now also deposits that same amount straight into the real Bank balance
// — spending doesn't just vanish, it moves into savings, same as the handful of purchases
// (movie tickets etc.) that already did this by hand before. One shared choke point instead of
// duplicating "sipDollars -= X; bankBalance += X;" at every single spend site in the file.
function spendSip(amount) { sipDollars -= amount; bankBalance += amount; }
function buyStockShares(symbol) {
  const price = stockPrices[symbol];
  if(!price) { showNotif('❌ Price not available yet — try again in a moment.'); return; }
  if(sipDollars < price) { sfx.nope(); showNotif('❌ Not enough S.I.P.!'); return; }
  spendSip(price);
  myStocks[symbol] = (myStocks[symbol] || 0) + 1;
  updateSIP();
  sfx.buy();
  refreshStockMarketUI();
  saveCurrentUser();
}
function sellStockShares(symbol) {
  const owned = myStocks[symbol] || 0;
  if(owned <= 0) return;
  const price = stockPrices[symbol] || 0;
  queueEarning(price, 0, 'Stock Sale');
  myStocks[symbol] = owned - 1;
  if(myStocks[symbol] <= 0) delete myStocks[symbol];
  updateSIP();
  sfx.coin();
  refreshStockMarketUI();
  saveCurrentUser();
}

// Bank interval started in startGame() so it doesn't fire during login/customization
function bankDeposit() {
  const amt = parseInt(document.getElementById('bankAmtInput').value);
  const msg = document.getElementById('bankMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > sipDollars) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent="You don't have that much!"; return; }
  spendSip(amt);
  bankBalance += amt;
  document.getElementById('sipAmount').textContent = sipDollars;
  document.getElementById('bankWalletDisplay').textContent = sipDollars.toLocaleString() + ' S.I.P.';
  document.getElementById('bankBalDisplay').textContent = bankBalance.toLocaleString() + ' S.I.P.';
  sfx.bank();
  msg.style.color = '#44ff88';
  msg.textContent = '✅ Deposited ' + amt.toLocaleString() + ' S.I.P.!';
  saveCurrentUser();
}
function bankWithdraw() {
  const amt = parseInt(document.getElementById('bankAmtInput').value);
  const msg = document.getElementById('bankMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > bankBalance) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent='Not enough in your bank!'; return; }
  bankBalance -= amt;
  sipDollars += amt;
  document.getElementById('sipAmount').textContent = sipDollars;
  document.getElementById('bankWalletDisplay').textContent = sipDollars.toLocaleString() + ' S.I.P.';
  document.getElementById('bankBalDisplay').textContent = bankBalance.toLocaleString() + ' S.I.P.';
  sfx.coin();
  msg.style.color = '#FFD700';
  msg.textContent = '✅ Withdrew ' + amt.toLocaleString() + ' S.I.P.!';
  saveCurrentUser();
}
// Same shape as bankDeposit/bankWithdraw above, just for Elite Coins against the new
// bankEliteBalance (see its declaration for why that starts absurdly high instead of at 0).
function bankEliteDeposit() {
  const amt = parseInt(document.getElementById('bankEliteAmtInput').value);
  const msg = document.getElementById('bankMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > eliteCoins) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent="You don't have that many 💎!"; return; }
  eliteCoins -= amt;
  bankEliteBalance += amt;
  updateElite();
  document.getElementById('bankEliteWalletDisplay').textContent = Math.floor(eliteCoins).toLocaleString() + ' 💎';
  document.getElementById('bankEliteBalDisplay').textContent = formatBigNum(bankEliteBalance) + ' 💎';
  sfx.bank();
  msg.style.color = '#66ccff';
  msg.textContent = '✅ Deposited ' + amt.toLocaleString() + ' 💎!';
  saveCurrentUser();
}
function bankEliteWithdraw() {
  const amt = parseInt(document.getElementById('bankEliteAmtInput').value);
  const msg = document.getElementById('bankMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > bankEliteBalance) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent='Not enough in the vault!'; return; }
  bankEliteBalance -= amt;
  eliteCoins += amt;
  updateElite();
  document.getElementById('bankEliteWalletDisplay').textContent = Math.floor(eliteCoins).toLocaleString() + ' 💎';
  document.getElementById('bankEliteBalDisplay').textContent = formatBigNum(bankEliteBalance) + ' 💎';
  sfx.coin();
  msg.style.color = '#FFD700';
  msg.textContent = '✅ Withdrew ' + amt.toLocaleString() + ' 💎!';
  saveCurrentUser();
}

// ─── ATMs — small standalone cash kiosks around the city (see buildATM(), game-zones.js, and its
// CITY_ZONES.push() call sites in buildCity(), game-buildings.js). Same real amount-input/
// validate/settle shape as bankDeposit()/bankWithdraw() above, just moving money between
// sipDollars and the new carried `cash` instead of between sipDollars and bankBalance — and
// deliberately NOT routed through spendSip() (game-customization.js): spendSip's whole job is
// "every S.I.P. spend also deposits the same amount into the Bank," which is exactly backwards
// for a withdrawal (it would leave the player with both the withdrawn cash AND a phantom deposit
// of the same amount sitting in bankBalance — free money out of nowhere). Direct sipDollars/cash
// manipulation here matches bankWithdraw()'s own style above, which has the same "moving OUT of
// the safe balance" shape and also skips spendSip() for the same reason.
function openATM() {
  if(document.pointerLockElement) document.exitPointerLock();
  isPointerLocked = false;
  document.getElementById('atmAmtInput').value = '';
  document.getElementById('atmMsg').textContent = '';
  refreshATMDisplay();
  document.getElementById('atmModal').style.display = 'flex';
}
function refreshATMDisplay() {
  document.getElementById('atmSipDisplay').textContent = sipDollars.toLocaleString() + ' S.I.P.';
  document.getElementById('atmCashDisplay').textContent = '$' + Math.floor(cash).toLocaleString();
}
function closeATM() {
  document.getElementById('atmModal').style.display = 'none';
  if(renderer && renderer.domElement) renderer.domElement.requestPointerLock();
}
function atmWithdraw() {
  const amt = parseInt(document.getElementById('atmAmtInput').value);
  const msg = document.getElementById('atmMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > sipDollars) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent="You don't have that much S.I.P.!"; return; }
  sipDollars -= amt;
  cash += amt;
  updateSIP();
  updateCash();
  refreshATMDisplay();
  sfx.coin();
  msg.style.color = '#FFD700';
  msg.textContent = '✅ Withdrew $' + amt.toLocaleString() + ' cash!';
  saveCurrentUser();
}
function atmDeposit() {
  const amt = parseInt(document.getElementById('atmAmtInput').value);
  const msg = document.getElementById('atmMsg');
  if(!amt || amt <= 0) { msg.style.color='#ff8888'; msg.textContent='Enter a valid amount!'; return; }
  if(amt > cash) { sfx.nope(); msg.style.color='#ff8888'; msg.textContent="You don't have that much cash!"; return; }
  cash -= amt;
  sipDollars += amt;
  updateCash();
  updateSIP();
  refreshATMDisplay();
  sfx.bank();
  msg.style.color = '#44ff88';
  msg.textContent = '✅ Deposited $' + amt.toLocaleString() + ' to S.I.P.!';
  saveCurrentUser();
}

function backToLogin() {
  if(shopSalesTimer){ clearInterval(shopSalesTimer); shopSalesTimer=null; } // don't let a staffed shop's timer outlive the logged-in account
  shopOpen = false;
  saveCurrentUser();
  currentUser = null;
  clearRemotePlayers();
  clearRemoteKillers();
  document.getElementById('customScreen').style.display = 'none';
  document.getElementById('loginScreen').style.display  = 'flex';
  loadLoginScreen();
}

