        ctx.fillStyle='#4a5a6a';ctx.beginPath();ctx.moveTo(w*.07,-h*.005);ctx.lineTo(w*.13,-h*.03);ctx.lineTo(w*.13,h*.01);ctx.closePath();ctx.fill();
