        function fig(x,y,sz,col,headCol){ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y,sz*.2,sz*.3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=headCol;ctx.beginPath();ctx.arc(x,y-sz*.28,sz*.15,0,Math.PI*2);ctx.fill();}
