        ctx.strokeStyle='rgba(90,90,90,.6)';ctx.lineWidth=sz*.03;ctx.beginPath();ctx.ellipse(sz*.58,0,sz*.03,sz*.22,0,0,Math.PI*2);ctx.stroke();
