        for(let i=0;i<5;i++){ctx.strokeStyle='rgba(120,170,200,.25)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,h*(.66+i*.055)+Math.sin(t+i)*3);ctx.lineTo(w,h*(.66+i*.055)+Math.cos(t+i)*3);ctx.stroke();}
