        if(t>3){ctx.fillStyle='#e94560';ctx.save();ctx.translate(w*.7,h*.55);ctx.rotate(t*3);ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(8,0);ctx.lineTo(0,8);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.restore();}
