  for(let i=-1;i<=1;i++){box(3,0.1,3, 0xcc3333,20+i*8,0.5,94);box(0.2,3,0.2, 0x888,20+i*8,0.5,94);box(2,0.5,2, 0xeeddcc,20+i*8,0.5,96);}
