  box(5,0.4,1, 0xaa7755,4,0.7,-52);   box(5,1.5,0.3, 0xaa7755,4,1,-52.6);
  box(6,0.5,6, 0x88aacc,-4,0.3,-60); box(0.5,3,0.5, 0xaaa,-4,1.5,-60); box(2,0.3,2, 0x88aacc,-4,3.2,-60);

