  box(0.1,1,0.1, 0x7a5030, ix-5,0.5,iz+0.7); box(0.1,1,0.1, 0x7a5030, ix-3,0.5,iz+0.7);
  box(0.1,1,0.1, 0x7a5030, ix-5,0.5,iz+1.7); box(0.1,1,0.1, 0x7a5030, ix-3,0.5,iz+1.7);
  // TV on right wall
